Ext.define('bcp.view.RequestTrackingBaseViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.requesttrackingbase',

    showView: function (view) {
        var model = this.getViewModel(),
            layout = this.getView().getLayout(),
            refs = this.getReferences(),
            list = refs.list,
            detail = refs.detail;

        if (view === 'list') {
            layout.setActiveItem(list);
        } else {
            layout.setActiveItem(detail);
        }

        //TODO: do we still need this?
        model.set('viewState', view);
    },

    onClReqChkboxChange: function (field, newValue, oldValue, eOpts) {
        var store = this.getStore('reqStore');
        if (newValue) {
            store.clearFilter();
        } else {
            store.addFilter({
                operator: '!=',
                property: 'statusCode',
                value: 10
            });
        }
    },

    onBackToList: function (button, e, eOpts) {
        //this.showView('list');
        this.redirectTo(this.view.routeId);
    },

    onViewDetail: function (button, e, eOpts) {
        var refs = this.getReferences(),
            list = refs.requestList,
            req = list.selection;

        if (req) {
            var reqId = req.get('requestId');
            this.redirectTo('#' + this.view.routeId + '/' + reqId);
        } else {
            Ext.Msg.Alert('Warning', 'Please select a request from the list.');
        }
    },

    onCopy: function (button, e, eOpts) {
        var url =
                bcp.config.Runtime.getServerBaseUrl() +
                'requests/' +
                this.getViewModel().get('record').get('requestId') +
                '/copy',
            me = this;

        Ext.Ajax.request({
            url: url,
            method: 'POST',
            scope: this,
            success: function (response) {
                //instead of stay in the view, open the copied request for the user
                bcp.util.CommonUtil.ajaxSuccessHandler(
                    response,
                    function (result) {
                        me.redirectTo('#newrequest/' + result.requestId);
                        Ext.Msg.alert(
                            'Success',
                            'The Selected request is copied and opened for you to edit.'
                        );
                    }
                );
            }
        });
    },

    onEditResubmit: function (button, e, eOpts) {
        var model = this.getViewModel(),
            rec = model.get('record'),
            status = rec.get('statusCode'),
            requestId = rec.data.requestId,
            newRecord = Ext.create('bcp.model.RequestRoute', {
                requestId: requestId
            }),
            me = this;
        //you can only resubmit if the request is rejected and routed back to you
        //3/15/18 added canceled also
        //added return for info also
        if (status === 11 || status === 10 || status == 14) {
            newRecord.set('typeId', 0);
            if (this.view.xtype == 'preparedrequests') {
                newRecord.set('statusId', 12);
                newRecord.set('routeTo', rec.get('creatorId'));
                newRecord.set('routeToName', rec.get('creatorName'));
            } else {
                newRecord.set('statusId', 1);
                newRecord.set('routeTo', rec.get('requesterId'));
                newRecord.set('routeToName', rec.get('requesterName'));
            }

            Ext.Ajax.request({
                url: bcp.config.Runtime.getServerBaseUrl() + 'routes',
                method: 'POST',
                jsonData: Ext.encode(newRecord.data),
                scope: this,
                success: function (response) {
                    bcp.util.CommonUtil.ajaxSuccessHandler(
                        response,
                        function (result) {
                            me.redirectTo('#newrequest/' + requestId);
                        }
                    );
                },
                failure: function (form, response) {
                    Ext.Msg.alert('Route Failed', response.result.statusText);
                }
            });
        } else {
            Ext.Msg.alert(
                'Warning',
                'Someone is working on the request and you cannot edit it.'
            );
        }
    },

    onCancelRequest: function (button, e, eOpts) {
        var model = this.getViewModel(),
            store = this.getStore('reqStore'),
            record = model.get('record'),
            currentStatus = record.get('statusCode'),
            newRoute = Ext.create('bcp.model.RequestRoute', {
                requestId: record.get('requestId'),
                statusId: 10
            }),
            me = this;

        if (currentStatus === 8) {
            Ext.Msg.alert(
                'Warning',
                'Please contact the Bankcard Holder to reject your request before cancelling this request.'
            );
            return;
        } else if (currentStatus === 9) {
            Ext.Msg.alert(
                'Warning',
                'Your request was already delivered and cannot be canceled.'
            );
            return;
        } else if (currentStatus === 10) {
            Ext.Msg.alert('Warning', 'Your request was already canceled.');
            return;
        } else if (currentStatus === 13) {
            Ext.Msg.alert('Warning', 'You cannot cancel a received request.');
            return;
        }

        newRoute.set('typeId', 8);
        if (this.view.xtype == 'preparedrequests') {
            newRoute.set('routeTo', record.get('creatorId'));
            newRoute.set('routeToName', record.get('creatorName'));
        } else {
            newRoute.set('routeTo', record.get('requesterId'));
            newRoute.set('routeToName', record.get('requesterName'));
        }

        // Ask user to confirm this action
        Ext.Msg.confirm(
            'Cancel Request Confirmation',
            'Are you sure you want to cancel this request?',
            function (result) {
                // User confirmed yes
                if (result == 'yes') {
                    Ext.Ajax.request({
                        url: bcp.config.Runtime.getServerBaseUrl() + 'routes',
                        method: 'POST',
                        jsonData: Ext.encode(newRoute.data),
                        scope: this,
                        success: function (response) {
                            bcp.util.CommonUtil.ajaxSuccessHandler(
                                response,
                                function (result) {
                                    Ext.Msg.alert(
                                        'Success',
                                        'Your request was canceled successfully.'
                                    );
                                    store.source.reload();
                                    me.showView('list');
                                }
                            );
                        },
                        failure: function (response) {
                            Ext.Msg.alert('Failed', response.result.statusText);
                        }
                    });
                }
            }
        );
    },

    onReload: function (button, e, eOpts) {
        this.getStore('reqStore').source.reload();
    },

    onSelect: function (rowmodel, record, index, eOpts) {
        var model = this.getViewModel(),
            refs = this.getReferences(),
            userId = model.get('loggedInUser').peopleId,
            requesterId = record.data.requesterId,
            status = record.data.statusCode;

        //binding doesn't work for these ui controls, so use code control it here
        if (refs.btnResubmit) {
            if (status === 11 || status === 10 || status == 14) {
                refs.btnResubmit.enable();
            } else {
                refs.btnResubmit.disable();
            }
        }

        if (refs.btnCancelReq) {
            if (
                status === 10 ||
                (this.view.xtype == 'preparedrequests' &&
                    record.data.creatorId !== userId) ||
                (this.view.xtype == 'requesttracking' && requesterId !== userId)
            ) {
                refs.btnCancelReq.disable();
            } else {
                refs.btnCancelReq.enable();
            }
        }

        //reload history data with the selected record
        refs.historyview
            .getController()
            .loadHistoryById(record.get('requestId'));
    },

    onViewAdded: function (component, container, pos, eOpts) {
        var model = this.getViewModel(),
            refs = this.getReferences(),
            store = {},
            rec = null,
            status = 0,
            reqStore = this.getStore('reqStore'),
            reqList = refs.requestList,
            userId = model.get('loggedInUser').peopleId;

        if (component.xtype == 'preparedrequests') {
            store = Ext.getStore('PreparedRequests');
            refs.btnResubmit.setText('Edit & Re-send');
            refs.viewTitleLabel.setText('Prepared Requests');
        } else if (component.xtype == 'requesttracking') {
            store = Ext.getStore('ActiveRequests');
            refs.btnResubmit.setText('Edit & Re-submit');
            refs.viewTitleLabel.setText('Submitted Requests');
        } else {
            refs.btnResubmit.destroy();
            refs.btnCancelReq.destroy();
            refs.cancelledReqChkbox.destroy();
            store = Ext.getStore('HistoricalRequests');
            refs.viewTitleLabel.setText('Received Requests');
        }
        reqStore.setSource(store);

        //by default, filter canceled reqs
        reqStore.addFilter({operator: '!=', property: 'statusCode', value: 10});

        //when actions within the view or its subview finishes, it should return to
        model.set('returnToView', this.view.routeId);

        //ensure that no one does the ordered item update (BH functions) in this view's item view; no longer needed
        //model.set('isBaoBch',false);

        reqList.setSelection(null);

        //received request view has no resubmit or cancel button
        if (refs.btnResubmit) {
            refs.btnResubmit.disable();
            refs.btnCancelReq.disable();
        }

        if (component && component.requestId && component.requestId !== 0) {
            //the request record should be prepared by the before action already
            rec = model.get('currentRequest');

            if (rec) {
                model.set('generalInfo', rec);
                model.set('record', rec);

                status = rec.get('statusCode');

                //detail view
                //binding doesn't work for these ui controls, so use code control it here
                if (refs.btnResubmit) {
                    if (status === 11 || status === 10 || status == 14) {
                        refs.btnResubmit.enable();
                    } else {
                        refs.btnResubmit.disable();
                    }
                    if (
                        status === 10 ||
                        (component.xtype == 'preparedrequests' &&
                            rec.data.creatorId !== userId) ||
                        (component.xtype == 'requesttracking' &&
                            rec.data.requesterId !== userId)
                    ) {
                        refs.btnCancelReq.disable();
                    } else {
                        refs.btnCancelReq.enable();
                    }
                }

                if (!refs.detail) {
                    Ext.suspendLayouts();
                    //add detail view
                    this.view.add({
                        xtype: 'readonlyrequest',
                        reference: 'detail',
                        flex: 1
                    });
                    Ext.resumeLayouts();
                }

                this.showView('detail');
            }
            //no no rec
        } else {
            //list view
            this.showView('list');
        }
    }
});
